const getTextFromCoordinatesOfCurrentPage = async (x = 400, y = 400) => {
    const { documentViewer } = WebViewer.getInstance().Core; 
    const doc = documentViewer.getDocument();
    if (doc) {
        const currentPageNum = documentViewer.getCurrentPage();
        const info = doc.getPageInfo(currentPageNum);
        const rect = new Core.Math.Rect(x, y, info.width, info.height);
        const text = await doc.getTextByPageAndRect(currentPageNum, rect);
        return text;
    } else {
        return "No document";
    }
};
await getTextFromCoordinatesOfCurrentPage(400, 400)

